<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api } from '../api/client'
import type { Project, Version } from '../types'
import { versionDifferences, versionTree } from '../types/versions'
import ComparePlayer from '../components/ComparePlayer.vue'
import VersionMetadata from '../components/VersionMetadata.vue'
import { useStudio } from '../stores/studio'
const route = useRoute(), router = useRouter(), studio = useStudio()
const projects = ref<Project[]>([]), versions = ref<Version[]>([]), projectId = ref(typeof route.query.project === 'string' ? route.query.project : '')
const aId = ref(typeof route.query.a === 'string' ? route.query.a : ''), bId = ref(''), error = ref(''), loading = ref(true)
const filtered = computed(() => versions.value.filter(v => !projectId.value || v.projectId === projectId.value))
const tree = computed(() => versionTree(filtered.value))
const a = computed(() => filtered.value.find(v => v.id === aId.value)), b = computed(() => filtered.value.find(v => v.id === bId.value))
const differences = computed(() => a.value && b.value ? versionDifferences(a.value, b.value) : [])
watch(filtered, values => { if (!values.some(v => v.id === aId.value)) aId.value = values[0]?.id ?? ''; if (!values.some(v => v.id === bId.value) || bId.value === aId.value) bId.value = values.find(v => v.id !== aId.value)?.id ?? '' })
async function load() { try { [projects.value, versions.value] = await Promise.all([api<Project[]>('/projects'), api<Version[]>('/versions')]); error.value = '' } catch (e) { error.value = (e as Error).message } finally { loading.value = false } }
async function branch(id: string) { if (await studio.branch(id)) await router.push('/studio'); else if (studio.error) error.value = studio.error }
onMounted(load)
watch(() => studio.task?.status, state => { if (state === 'completed') void load() })
</script>
<template><div class="page-heading"><div><span class="eyebrow">EXPLORE YOUR VERSIONS</span><h1>版本树与 A/B 对比</h1><p>保留每条创作路径，找到更贴近故事的声音。</p></div><button class="button" @click="load">刷新版本</button></div><p v-if="error" class="error message" role="alert">{{ error }}</p><label class="search-label">筛选项目<select v-model="projectId"><option value="">全部项目</option><option v-for="project in projects" :key="project.id" :value="project.id">{{ project.name }}</option></select></label><p v-if="loading" class="muted">正在读取版本…</p><section v-else-if="!filtered.length" class="card empty-state"><h2>还没有可比较的版本</h2><p>先生成一段音乐，然后从作品库创建分支。</p><RouterLink class="button" to="/studio">前往创作台</RouterLink></section><template v-else><section class="card"><h2>版本树</h2><p class="small-note">根节点是独立生成；下一级来自父版本的设计稿。创建分支只生成草稿，点击生成音乐后才新增音频版本。</p><ul class="version-tree"><li v-for="node in tree" :key="node.version.id" :style="{ marginLeft: `${Math.min(node.depth, 8) * 18}px` }" :data-version-id="node.version.id"><div class="tree-label"><span class="tree-connector">{{ node.depth ? '↳' : '●' }}</span><div><strong>{{ node.version.title }}</strong><small>{{ node.version.id.slice(0, 8) }} · {{ node.version.blueprint.bpm }} BPM · {{ node.version.provider === 'mock' ? '模拟' : 'Lyria' }}{{ node.version.parentVersionId ? ' · 父版本 ' + node.version.parentVersionId.slice(0, 8) : ' · 独立版本' }}</small></div></div><div class="version-actions"><button class="button small" @click="aId = node.version.id">设为 A</button><button class="button small" @click="bId = node.version.id">设为 B</button><button class="text-button" @click="branch(node.version.id)" :disabled="studio.busy || studio.active">创建分支</button></div></li></ul></section><section class="card compare-select"><div class="form-grid two"><label>版本 A<select v-model="aId"><option v-for="v in filtered" :key="v.id" :value="v.id">{{ v.title }} · {{ v.blueprint.bpm }} BPM · {{ v.id.slice(0, 8) }}</option></select></label><label>版本 B<select v-model="bId"><option value="">请选择第二个版本</option><option v-for="v in filtered" :key="v.id" :value="v.id">{{ v.title }} · {{ v.blueprint.bpm }} BPM · {{ v.id.slice(0, 8) }}</option></select></label></div><p v-if="aId && aId === bId" class="muted">当前两侧选择了同一版本，请选择另一个版本进行比较。</p></section><template v-if="a && b && a.id !== b.id"><ComparePlayer :a="a" :b="b" /><section class="card"><h2>参数与提示词差异 <span class="subtle-tag">{{ differences.length }} 项</span></h2><p v-if="!differences.length" class="muted">生成参数相同；模型仍可能生成不同音乐。</p><div v-else class="diff-table-wrap"><table class="diff-table"><thead><tr><th>字段</th><th>版本 A</th><th>版本 B</th></tr></thead><tbody><tr v-for="difference in differences" :key="difference.label"><th>{{ difference.label }}</th><td><pre>{{ difference.a }}</pre></td><td><pre>{{ difference.b }}</pre></td></tr></tbody></table></div></section><div class="ab-metadata"><section class="card"><h2>A · {{ a.title }}</h2><VersionMetadata :version="a" @saved="load" /></section><section class="card"><h2>B · {{ b.title }}</h2><VersionMetadata :version="b" @saved="load" /></section></div></template></template></template>
